import{_ as o,r as n,o as p,c as i,e as a,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Using Laravel Packages - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"Configuration Files","slug":"configuration-files","link":"#configuration-files","children":[]},{"level":3,"title":"Aliases & Service Providers","slug":"aliases-service-providers","link":"#aliases-service-providers","children":[]},{"level":3,"title":"Migrations & Models","slug":"migrations-models","link":"#migrations-models","children":[]}],"relativePath":"3.x/extend/resources/using-laravel-packages.md","filePath":"3.x/extend/resources/using-laravel-packages.md"}'),r={name:"3.x/extend/resources/using-laravel-packages.md"};function u(g,s,d,k,f,h){const e=n("pre-heading"),t=n("post-heading");return p(),i("div",null,[a(e),s[0]||(s[0]=c("h1",null,"Using Laravel Packages",-1)),a(t),s[1]||(s[1]=l(`<p>When including Laravel packages in October CMS plugins there are a few things to take note of.</p><h3 id="configuration-files"><a href="#configuration-files" class="header-anchor">#</a> Configuration Files</h3><p>Laravel packages will often provide configuration files, you should duplicate this configuration to your plugin&#39;s directory. For example, if the file was named <strong>purifier.php</strong> and contained some basic configuration values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;encoding&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;UTF-8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;finalize&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;cachePath&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">storage_path</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app/purifier&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;cacheFileMode&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">0755</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>Copy this file to your plugin directory, for example, <strong>plugins/acme/blog/config/purifier.php</strong>. It is important to copy and maintain the entire file as any missing keys will not be inherited from the base configuration.</p><p>Next you should transfer the contents of your plugin&#39;s configuration to the package configuration inside the <code>boot()</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;purifier&#39;</span><span class="token punctuation">,</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::purifier&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>This will set all the package config values to be that of your plugin config values. The following values would then be equal.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;purifier.encoding&#39;</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::purifier.encoding&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Now you are free to provide the packages configuration values the same way you would with regular plugin configuration values and the <a href="./../settings/file-settings.html">standard configuration approach</a>.</p><h3 id="aliases-service-providers"><a href="#aliases-service-providers" class="header-anchor">#</a> Aliases &amp; Service Providers</h3><p>If the Laravel package contains any Service Providers and Aliases, you should manually register them in your plugins using the the <code>App</code> facade in the <code>register()</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Register the aliases provided by the packages used by your plugin</span>
    <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">registerClassAlias</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Purifier&#39;</span><span class="token punctuation">,</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Mews<span class="token punctuation">\\</span>Purifier<span class="token punctuation">\\</span>Facades<span class="token punctuation">\\</span>Purifier</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Register the service providers provided by the packages used by your plugin</span>
    <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Mews<span class="token punctuation">\\</span>Purifier<span class="token punctuation">\\</span>PurifierServiceProvider</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="migrations-models"><a href="#migrations-models" class="header-anchor">#</a> Migrations &amp; Models</h3><p>Laravel packages that interact with the database will often include their own database migrations and Eloquent models. You should duplicate these migrations and models to your plugin&#39;s directory.</p><p>Be sure to change the Model classes to extend the base <code>October\\Rain\\Database\\Model</code> class instead of the base Laravel Eloquent model class to take advantage of the extended technology features found in October CMS.</p><p>It is also a good idea to rename the database tables and prefix them with your author code and plugin name. For example, a table with the name <code>posts</code> should be renamed to <code>rainlab_blog_posts</code>.</p>`,17))])}const y=o(r,[["render",u]]);export{v as __pageData,y as default};
